CREATE TABLE houses (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, colors VARCHAR(150) NOT NULL, founder VARCHAR(150) NOT NULL);
CREATE TABLE teachers (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name VARCHAR(150) NOT NULL, house_id INTEGER NOT NULL REFERENCES houses(id) ON DELETE RESTRICT);
CREATE TABLE students (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name VARCHAR(150) NOT NULL, year INTEGER NOT NULL CHECK (year BETWEEN 1 AND 7), house_id INTEGER NOT NULL REFERENCES houses(id) ON DELETE RESTRICT);
CREATE TABLE courses (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name VARCHAR(150) NOT NULL, teacher_id INTEGER NOT NULL REFERENCES teachers(id) ON DELETE RESTRICT);
CREATE TABLE course_students (course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE, PRIMARY KEY(course_id,student_id));
